def test_the_transport_sleeps_and_reads_the_clock_it_was_given() -> None:
    timeline = Timeline()
    with make(Recorder(), timeline) as transport:
        start = transport.now()
        transport.sleep(3)
        assert transport.now() == start + 3
        assert transport.deadline(None) is None
    assert timeline.sleeps == [3]
